function pic(file, widthEMU=5715000){
  const s=size(file); const hEMU=Math.round(widthEMU*s.h/s.w);
  return new Paragraph({alignment:AlignmentType.CENTER,spacing:{before:140,after:100},
    children:[new ImageRun({data:img(file),transformation:{width:Math.round(widthEMU/9144),height:Math.round(hEMU/9144)},type:"png"})]});
}
function tbl(hdr,rows,w){
  const tot=w.reduce((a,b)=>a+b,0);
  return new Table({width:{size:tot,type:WidthType.DXA},columnWidths:w,rows:[
    new TableRow({tableHeader:true,children:hdr.map((x,i)=>new TableCell({borders:hbs,width:{size:w[i],type:WidthType.DXA},
      shading:{fill:BLUE,type:ShadingType.CLEAR},margins:{top:80,bottom:80,left:110,right:110},
      children:[new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:x,bold:true,size:19,color:"FFFFFF",font:AR})]})]}))}),
    ...rows.map((r,ri)=>new TableRow({children:r.map((c,ci)=>new TableCell({borders:bds,width:{size:w[ci],type:WidthType.DXA},
      shading:{fill:ri%2===0?"EBF3FB":"FFFFFF",type:ShadingType.CLEAR},margins:{top:70,bottom:70,left:110,right:110},
      children:[new Paragraph({children:[new TextRun({text:c,size:19,font:AR})]})]}))}))]});
}

